/*
 * Pro tips
 * - A closing bracket must match the most recent unmatched opening bracket: think LIFO.
 * - Check that the stack is nonempty before inspecting or popping it.
 * - A successful scan is not enough: the stack must also be empty at the end.
 * - Check nested brackets, crossing pairs like ([)], a leading closer, and leftover openers.
 * - Assumes bracket-only input. Complexity: O(n) time, O(n) worst-case stack space.
 */

import java.util.Map;
import java.util.Scanner;
import java.util.Stack;

class Solution {
    public static boolean validParentheses(String s) {
        Stack<Character> stack = new Stack<>();
        Map<Character, Character> pairs = Map.of(')', '(', '}', '{', ']', '[');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (pairs.containsKey(c)) {
                if (!stack.isEmpty() && stack.peek() == pairs.get(c)) {
                    stack.pop();
                } else {
                    return false;
                }
            } else {
                stack.push(c);
            }
        }
        return stack.isEmpty();
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();
        boolean res = validParentheses(s);
        System.out.println(res);
    }
}
